import { appConfig } from '~/shared/config';

export const getVideoUrl = (name: string, prefix?: string) => {
  const baseUrl = new URL(import.meta.url);
  return new URL(`/mp4/${prefix ?? ''}${name}.mp4`, baseUrl).href;
};
export const lazyLoadOfframpVideo = async (path: string) => {
  const videoUrl = getVideoUrl(appConfig.BANK_CODE, path);
  return videoUrl;
};

export const lazyLoadTransVideo = async (path: string) => {
  const videoUrl = getVideoUrl(appConfig.BANK_CODE, path);
  return videoUrl;
};
