import { MutableRefObject } from 'react';
import { StatusType, SuccessType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

/**
 * 트랜잭션 상태에 따른 처리를 담당하는 함수를 생성합니다.
 *
 * @param transactionId 트랜잭션 ID
 * @param intervalId 인터벌 ID (clearInterval 용)
 * @param handlers resolve/reject 핸들러
 * @param onNext 성공 시 다음 단계로 넘어가는 콜백
 * @param onError 에러 발생 시 콜백
 * @param counter 카운터 참조 (시도 횟수 추적용)
 */
export const createTransactionStatusHandlers = (
  transactionId: string,
  intervalId: ReturnType<typeof setInterval>,
  {
    resolve,
    reject,
    onNext,
    onError,
    counter,
  }: {
    resolve: () => void;
    reject: (error: Error) => void;
    onNext: (trnscId: string) => void;
    onError: (error: Error) => void;
    counter: MutableRefObject<number>;
  },
) => ({
  [SuccessType.성공]: () => {
    clearInterval(intervalId);
    onNext(transactionId);
    resolve();
  },
  [SuccessType.실패]: () => {
    clearInterval(intervalId);
    const error = new Error('결제 실패');
    onError(error);
    reject(error);
  },
  default: () => {
    counter.current += 1;
  },
});

/**
 * 트랜잭션 상태를 폴링하는 함수
 *
 * @param options 폴링 옵션
 * @returns Promise<void>
 */
export const pollTransactionStatus = async ({
  transactionId,
  maxRetries = 3,
  intervalMs = 1000,
  resultSearch,
  openAlertDialog,
  onNext,
  onError,
  counter,
}: {
  transactionId: string;
  maxRetries?: number;
  intervalMs?: number;
  resultSearch: (params: { tbPayMastr: { bchainReqstId: string } }) => Promise<any>;
  openAlertDialog: (params: { message: string; onConfirmClick: () => void }) => void;
  onNext: (trnscId: string) => void;
  onError: (error: Error) => void;
  counter: MutableRefObject<number>;
}) => {
  counter.current = 0;

  return new Promise<void>((resolve, reject) => {
    const id = setInterval(async () => {
      // 최대 시도 횟수 초과 시 처리
      if (counter.current >= maxRetries) {
        clearInterval(id);
        openAlertDialog({
          message: i18n.t('paymentDelayMsg'),
          onConfirmClick: () => {
            onNext(transactionId);
            resolve();
          },
        });
        return;
      }

      try {
        const response = await resultSearch({
          tbPayMastr: { bchainReqstId: transactionId },
        });

        const statusHandlers = createTransactionStatusHandlers(transactionId, id, {
          resolve,
          reject,
          onNext,
          onError,
          counter,
        });

        // Execute the appropriate handler based on status or use default
        (statusHandlers[response?.trnscSttusCd as keyof typeof statusHandlers] || statusHandlers.default)();
      } catch (error) {
        clearInterval(id);
        onError(error instanceof Error ? error : new Error('트랜잭션 상태 조회 실패'));
        reject(error);
      }
    }, intervalMs);
  });
};

export const statusHandlers = (
  transactionId: string,
  aliasNm: string,
  {
    onNext,
    onError,
  }: {
    onNext: (params: { trnscId: string; reqAliasNm: string }) => void;
    onError: (error: Error) => void;
  },
) => ({
  [StatusType.성공]: () => {
    onNext({ trnscId: transactionId, reqAliasNm: aliasNm });
  },
  [StatusType.실패]: () => {
    const error = new Error('결제 실패');
    onError(error);
  },
});

export const paymentStatusHandlers = (
  transactionId: string,
  reqAliasNm: string,
  {
    onNext,
    amt,
    errorMessage,
  }: {
    onNext: (params: { trnscId: string; reqAliasNm: string; amt: string }) => void;
    amt: string;
    errorMessage?: string;
  },
) => ({
  [StatusType.성공]: () => {
    onNext({ trnscId: transactionId, reqAliasNm, amt });
  },
  [StatusType.실패]: () => {
    throw new Error(errorMessage ?? '결제 실패');
  },
});
