import { useState, useCallback, useEffect } from 'react';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import { getVideoUrl, lazyLoadOfframpVideo, lazyLoadTransVideo } from './load-video';

type ExchangeProcessVideoProps = {
  trnscTypeCd: TrnscTypeCd;
};

export const useExchangeProcessVideo = ({ trnscTypeCd }: ExchangeProcessVideoProps) => {
  const [movUrl, setMovUrl] = useState('');
  const loadVideoUrl = useCallback(async () => {
    let url;

    if (trnscTypeCd === TrnscTypeCd.전환입금) {
      url = getVideoUrl('on_ramp', 'on_ramp/'); // Assuming onRamp is a direct video URL
    } else if (trnscTypeCd === TrnscTypeCd.예금전환) {
      url = await lazyLoadOfframpVideo('off_ramp/off_ramp_');
    } else {
      url = await lazyLoadTransVideo('transfer/transfer_');
    }

    setMovUrl(url);
  }, [trnscTypeCd]);

  useEffect(() => {
    loadVideoUrl();
  }, []);

  return { movUrl };
};
